import { z } from 'zod';

export const pinLoginSchema = z.object({
  pin: z.string().trim().min(1, 'PIN is required'),
});

export const managerApprovalSchema = z.object({
  action: z.string().trim().min(1).optional(),
  reason: z.string().trim().min(1).optional(),
});

export const orderSchema = z.object({
  // Generated by the POS once per sale and resent unchanged on every retry
  // (offline queue replays included), so the backend can recognise a sale it
  // has already recorded instead of saving it twice. Optional so older POS
  // builds still in the field keep working.
  clientOrderId: z.uuid().optional(),
  // Only sent for a sale rung up offline and synced later: when it actually
  // happened, and the exchange rate the register charged it at.
  soldAt: z.iso.datetime().optional(),
  exchangeRateRielPerUsd: z.number().positive().optional(),
  items: z.array(z.object({
    productId: z.string().min(1),
    productName: z.string().min(1),
    quantity: z.number().int().positive(),
    unitPrice: z.number().nonnegative(),
    selectedModifiers: z.array(z.object({
      id: z.string().min(1),
      name: z.string().min(1),
      priceExtra: z.number().nonnegative(),
    })).optional(),
  })).min(1),
  paymentMethod: z.enum(['CASH', 'CARD', 'QR_CODE']),
  amountTenderedUsd: z.number().nonnegative().optional(),
  amountTenderedRiel: z.number().nonnegative().optional(),
  taxAmount: z.number().nonnegative().optional(),
  discountAmount: z.number().nonnegative().optional(),
  // A Mobile Pay sale paid through a Bakong KHQR for its exact amount: the
  // QR's md5, which Bakong confirmed as paid (POST /api/payments/khqr).
  khqrMd5: z.string().regex(/^[a-f0-9]{32}$/).optional(),
});

// A manager's correction of a completed sale (PUT /api/orders/:id): the full
// new list of items, payment method and discount, and why.
export const orderEditSchema = z.object({
  items: orderSchema.shape.items,
  paymentMethod: orderSchema.shape.paymentMethod,
  discountAmount: z.number().nonnegative(),
  reason: z.string().trim().min(1, 'A reason is required').max(200),
});

export const voidOrderSchema = z.object({
  reason: z.string().trim().min(1, 'A reason is required').max(200),
});

export const exchangeRateSchema = z.object({
  exchangeRateRielPerUsd: z.number().positive(),
});

export const mainCurrencySchema = z.object({
  mainCurrency: z.enum(['USD', 'KHR']),
});

export const taxSettingSchema = z.object({
  taxEnabled: z.boolean(),
});

export const inventoryAdjustmentSchema = z.object({
  inventoryItemId: z.string().min(1),
  quantityChanged: z.number(),
  type: z.enum(['RESTOCK', 'WASTAGE', 'AUDIT_CORRECTION']),
  notes: z.string().trim().optional(),
});

export const inventoryItemSchema = z.object({
  name: z.string().trim().min(1, 'Name is required'),
  unit: z.enum(['grams', 'ml', 'pieces']),
  reorderThreshold: z.number().nonnegative(),
  costPerUnit: z.number().nonnegative(),
  isActive: z.boolean().optional().default(true),
});

export const userRoleSchema = z.enum(['CASHIER', 'BARISTA', 'MANAGER', 'ADMIN']);

export const userCreateSchema = z.object({
  name: z.string().trim().min(1, 'Name is required'),
  pin: z.string().regex(/^\d{4}$/, 'PIN must be exactly 4 digits'),
  role: userRoleSchema,
  isActive: z.boolean().optional().default(true),
});

export const userUpdateSchema = z.object({
  name: z.string().trim().min(1, 'Name is required'),
  role: userRoleSchema,
  isActive: z.boolean(),
  pin: z.string().regex(/^\d{4}$/, 'PIN must be exactly 4 digits').optional(),
});

export const categorySchema = z.object({
  name: z.string().trim().min(1, 'Name is required'),
  sortOrder: z.number().int().optional().default(0),
});

// The full category list in its new order - sortOrder becomes each id's index.
export const categoryOrderSchema = z.object({
  categoryIds: z.array(z.string().min(1)).min(1, 'At least one category is required'),
});

export const productSchema = z.object({
  categoryId: z.string().min(1, 'Category is required'),
  name: z.string().trim().min(1, 'Name is required'),
  basePrice: z.number().nonnegative(),
  sku: z.string().trim().optional(),
  imageUrl: z.string().trim().optional(),
  isAvailable: z.boolean().optional().default(true),
});

// A group is saved as a whole: options carrying an `id` are updated in place
// (keeping their recipe links and order history), options without one are
// created, and existing options left out of the list are removed.
export const modifierGroupSchema = z.object({
  name: z.string().trim().min(1, 'Name is required'),
  minSelection: z.number().int().min(0),
  maxSelection: z.number().int().min(1),
  options: z.array(z.object({
    id: z.string().min(1).optional(),
    name: z.string().trim().min(1, 'Option name is required'),
    priceExtra: z.number().nonnegative(),
  })).min(1, 'Add at least one option'),
  productIds: z.array(z.string().min(1)).optional().default([]),
}).refine((data) => data.minSelection <= data.maxSelection, {
  message: 'Minimum selection cannot exceed maximum selection',
}).refine((data) => data.minSelection <= data.options.length, {
  message: 'Minimum selection cannot exceed the number of options',
});

export const recipeUpdateSchema = z.object({
  productId: z.string().min(1).optional(),
  modifierId: z.string().min(1).optional(),
  ingredients: z.array(z.object({
    inventoryItemId: z.string().min(1),
    quantityRequired: z.number().positive('Quantity must be greater than zero'),
  })),
}).refine((data) => Boolean(data.productId) !== Boolean(data.modifierId), {
  message: 'Exactly one of productId or modifierId must be provided',
});

// --- POS settings (store-wide, managed from IMS and the POS Settings tab) ---
// Limits match what the POS has always enforced locally.

export const POS_PAYMENT_METHODS = ['CASH', 'CARD', 'QR_CODE'] as const;
export const POS_SOCIAL_PLATFORMS = ['FACEBOOK', 'INSTAGRAM', 'TIKTOK', 'TELEGRAM', 'WEBSITE', 'OTHER'] as const;

const isWholeCents = (amount: number) => Math.abs(Math.round(amount * 100) - amount * 100) < 1e-6;
const contactEntry = z.string().trim().min(1).max(60);

export const posSettingsSchema = z.object({
  // Empty = the POS shows its default app title.
  storeName: z.string().trim().max(60),
  storeDetails: z.object({
    address: z.string().max(200),
    phones: z.array(contactEntry).max(3),
    emails: z.array(contactEntry).max(3),
    socials: z.array(z.object({ platform: z.enum(POS_SOCIAL_PLATFORMS), handle: contactEntry })).max(3),
  }),
  // At least one, so checkout always has a way to take payment.
  paymentMethods: z.array(z.enum(POS_PAYMENT_METHODS)).min(1)
    .refine((methods) => new Set(methods).size === methods.length, 'Payment methods must not repeat'),
  // Quick-tender buttons: USD to the cent, riel in whole hundreds.
  fastCash: z.object({
    USD: z.array(z.number().positive().refine(isWholeCents, 'USD amounts are to the cent')).max(10),
    KHR: z.array(z.number().positive().refine((amount) => amount % 100 === 0, 'Riel amounts are whole hundreds')).max(10),
  }),
  // imageUrl as returned by POST /api/upload.
  khqrBanks: z.array(z.object({
    id: z.string().min(1).max(64),
    name: z.string().trim().min(1).max(60),
    imageUrl: z.string().min(1).max(500),
  })).max(10),
  // The register's screens, receipts and customer display.
  language: z.enum(['en-US', 'km-KH']),
  // Leave items marked unavailable (sold out) off the register's menu,
  // instead of showing them greyed out.
  hideUnavailableItems: z.boolean(),
  // The store's Bakong account, for Mobile Pay QRs with the exact amount
  // (KHQR). An empty accountId turns them off - the bank QR images remain.
  // Lengths are the KHQR standard's limits.
  bakong: z.object({
    accountId: z.union([z.literal(''), z.string().trim().regex(/^[^\s@]+@[^\s@]+$/).max(32)]),
    merchantName: z.string().trim().max(25),
    merchantCity: z.string().trim().max(15),
  }),
});

// POST /api/payments/khqr - a KHQR for one sale's total, in the currency
// shown to the customer.
export const khqrRequestSchema = z.object({
  amount: z.number().positive(),
  currency: z.enum(['USD', 'KHR']),
});

// PUT /api/settings/bakong-credential - the email registered for the Bakong
// Open API, used to get the token for checking payments.
export const bakongCredentialSchema = z.object({
  registeredEmail: z.email(),
});

// PUT /api/settings/pos - any subset of the sections; the rest are kept.
export const posSettingsUpdateSchema = posSettingsSchema.partial()
  .refine((update) => Object.keys(update).length > 0, 'Nothing to update');

